// RunBase runs every check — generated and yours — against every
// harness.
//
//	RunBase(t,
//		BaseHarness[*InMemory]{Name: "in-memory", New: NewInMemory},
//		BaseSuite.Without(BaseSuite.Checks.Ping.Smoke()),
//	)
func RunBase(
	t *testing.T, opts ...BaseRunOpt,
) {
	t.Helper()
	var rc baseRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	fx := baseNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	// Between folding and running: a misused run reports every fix it
	// needs and executes nothing, rather than reporting one and leaving
	// the rest to be found a cycle at a time.
	rc.Fail(t, "RunBase")
	suite.Run(t,
		baseSuite().With(rc.Extra...).Without(rc.Drops...),
		rc.Subjects...)
}

// ProveBase drives each of your rows against the defect it names.
//
// A row with no ProvenBy is not skipped — it is held to saying why
// through Argued. The parity gate refuses a Proven claim with no
// evidence and evidence for a claim nobody made, in both directions, so
// this is where "proven able to fail" stops being prose.
func ProveBase(
	t *testing.T, checks BaseChecks,
) {
	t.Helper()
	// The RUN's config, not the derived one: a check proven at default
	// pools carries no evidence about the pools a run actually uses.
	fx := baseNewFixture()
	bound := make([]suite.Check[Base], 0, len(checks))
	defects := prove.Defects[Base]{}
	for _, row := range checks {
		bd, err := row.bind(fx)
		if err != nil {
			t.Fatalf("ProveBase: %v", err)
		}
		bound = append(bound, bd)
		if row.ProvenBy == nil {
			continue
		}
		sub, err := row.ProvenBy.Subject()
		if err != nil {
			t.Fatalf("ProveBase: check %q: defect: %v", bd.ID, err)
		}
		defects[bd.ID] = prove.Defect[Base]{
			Subject: sub, Reason: row.ProvenReason,
		}
	}
	prove.All(t, bound, defects)
}

